package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.function.Consumer;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Unit tests for CommandLine.hasOption(char)
 */
public class CommandLineHasOptionCharTest {

    @Test
    public void testHasOptionDelegatesToHasOptionString_andPassesCorrectString() throws Exception {
        // Create an anonymous subclass that overrides hasOption(String) to capture the passed string
        CommandLine cmd = new CommandLine() {
            // capture field to be inspected via reflection
            private String captured;
            @Override
            public boolean hasOption(final String optionName) {
                this.captured = optionName;
                // Return true only for "a" to exercise both true/false results
                return "a".equals(optionName);
            }
        };

        // Call hasOption(char) for 'a' -> should delegate and return true
        assertTrue(cmd.hasOption('a'));

        // Call hasOption(char) for 'b' -> should delegate and return false
        assertFalse(cmd.hasOption('b'));

        // Using reflection to read the private 'captured' field from the anonymous subclass instance
        Field capturedField = cmd.getClass().getDeclaredField("captured");
        capturedField.setAccessible(true);

        // After last call with 'b', captured should be "b"
        Object capturedValue = capturedField.get(cmd);
        assertEquals("b", capturedValue, "The delegate should receive the string representation of the char ('b')");

        // Now call again with 'a' and verify field updates
        assertTrue(cmd.hasOption('a'));
        capturedValue = capturedField.get(cmd);
        assertEquals("a", capturedValue, "The delegate should receive the string representation of the char ('a')");
    }

    @Test
    public void testPrivateConstructorViaReflection_setsFieldsCorrectly() throws Exception {
        // Prepare lists to pass to the private constructor
        List<String> args = new LinkedList<>();
        args.add("one");
        args.add("two");

        List<Option> options = new ArrayList<>();

        // Obtain the private constructor CommandLine(List, List, Consumer)
        Constructor<CommandLine> ctor = CommandLine.class.getDeclaredConstructor(List.class, List.class, java.util.function.Consumer.class);
        ctor.setAccessible(true);

        // Invoke private constructor with null deprecatedHandler (allowed by implementation)
        CommandLine cmd = ctor.newInstance(args, options, null);
        assertNotNull(cmd);

        // Use reflection to inspect private final fields 'args' and 'options' to ensure constructor wired them
        Field argsField = CommandLine.class.getDeclaredField("args");
        Field optionsField = CommandLine.class.getDeclaredField("options");
        argsField.setAccessible(true);
        optionsField.setAccessible(true);

        Object argsFieldValue = argsField.get(cmd);
        Object optionsFieldValue = optionsField.get(cmd);

        // Verify that the fields reference the same objects passed to constructor
        assertSame(args, argsFieldValue, "The 'args' field should reference the list provided to the constructor");
        assertSame(options, optionsFieldValue, "The 'options' field should reference the list provided to the constructor");
    }
}

